splay:grid;grid-template-columns:repeat(3,1fr);gap:7px}.metric{border:1px solid #000;border-radius:9px;padding:10px}.metric strong{display:block;font-size:18px}.metric small{display:block;color:rgba(0,0,0,.58)}.flow{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.arr{color:#ff008c;font-weight:900}.phgate{border:2px solid #000;border-radius:10px;padding:10px;margin-top:9px}.phgate b{color:#ff008c}.paths{display:grid;gap:8px}.path{border:1px solid #000;border-radius:10px;overflow:hidden}.path summary{list-style:none;cursor:pointer;display:grid;grid-template-columns:34px 1.2fr 1fr;gap:10px;padding:10px 12px;align-items:center}.path summary b{color:#ff008c}.path-body{border-top:1px solid #000;padding:10px 12px;display:grid;grid-template-columns:repeat(5,1fr);gap:8px}@media(max-width:900px){body{overflow:auto}.shell{height:auto;display:block}.stage{overflow:visible}.panel,.panel.active,.section{height:auto;overflow:visible}.drug summary{grid-template-columns:34px 1fr}.drug summary span{grid-column:2}.branches,.matrix,.path-body{grid-template-columns:1fr 1fr}.event{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}.compare-wrap{max-height:none}}@media(max-width:600px){.shell{padding:8px}.top{align-items:flex-start;flex-direction:column}.nav{position:sticky;top:0;background:#fff;padding:6px 0;z-index:5}.nav button{font-size:10px}.branches,.matrix,.path-body,.metrics{grid-template-columns:1fr}.chain{padding-bottom:8px}h2{font-size:20px}.rule{font-size:14px}}
